package p8mutation

import "time"

func optimisticConcurrencyPhysicalMutations() []Mutation {
	gate := func(pkg, test string) Gate { return Gate{Directory: "go", Package: pkg, Test: test} }
	return []Mutation{
		{Label: "CONCURRENCY_PHYSICAL_OMITS_CANONICAL_POINTER", Summary: "erase the table concurrency identity before canonical bytes and fingerprinting", Patches: []Patch{{Path: "go/internal/physical/normalize.go", Before: "result.OptimisticConcurrency = cloneFieldID(table.OptimisticConcurrency)", After: "result.OptimisticConcurrency = nil"}}, Gate: gate("./internal/physical", "TestOptimisticConcurrencyPhysicalV3ProjectionIsCanonicalAndClosed"), Timeout: 2 * time.Minute},
		{Label: "CONCURRENCY_POSTGRES_OMITS_CATALOG_RECONCILIATION", Summary: "drop logical concurrency metadata after PostgreSQL catalog introspection", Patches: []Patch{{Path: "go/internal/provider/postgresql/introspect.go", Before: "value := field\n\t\tactual.Tables[actualIndex].OptimisticConcurrency = &value", After: "value := field\n\t\t_ = value"}}, Gate: gate("./internal/provider/postgresql", "TestPostgreSQLIntrospectionReconcilesConcurrencyOnlyAfterExactCatalogTableProof"), Timeout: 2 * time.Minute},
		{Label: "CONCURRENCY_REVIEWED_EDGE_USES_MUTABLE_PLANNER", Summary: "route the retained v2-to-v3 replay through the mutable current planner", Patches: []Patch{{Path: "go/internal/migration/diff.go", Before: "return diffOptimisticConcurrencyV2ToV3Tagged(before, after)", After: "return diffSchemas(before, after, true, false)"}}, Gate: gate("./internal/migration", "TestReviewedTransitionEntrypointsDoNotRouteThroughMutablePlannerSource"), Timeout: 2 * time.Minute},
		{Label: "CONCURRENCY_POSTGRES_INITIALIZES_TWO", Summary: "initialize existing PostgreSQL rows to a value other than the runtime-owned one", Patches: []Patch{{Path: "go/internal/provider/postgresql/migrate.go", Before: `return []string{fmt.Sprintf("UPDATE %s SET %s = 1", qualified(r.schema.Namespace.Name, after.Name), quote(column.Name))}, nil`, After: `return []string{fmt.Sprintf("UPDATE %s SET %s = 2", qualified(r.schema.Namespace.Name, after.Name), quote(column.Name))}, nil`}}, Gate: gate("./internal/provider/postgresql", "TestPlanIncrementalInitializesEveryConcurrencyValueToExactlyOne"), Timeout: 2 * time.Minute},
		{Label: "CONCURRENCY_POSTGRES_PROVES_TWO", Summary: "weaken the typed PostgreSQL postcondition to prove the wrong value", Patches: []Patch{{Path: "go/internal/provider/postgresql/migrate.go", Before: `return quote(condition.column) + " IS DISTINCT FROM 1", nil`, After: `return quote(condition.column) + " IS DISTINCT FROM 2", nil`}}, Gate: gate("./internal/provider/postgresql", "TestPlanIncrementalInitializesEveryConcurrencyValueToExactlyOne"), Timeout: 2 * time.Minute},
		{Label: "CONCURRENCY_POSTGRES_INVENTS_DATABASE_DEFAULT", Summary: "invent DEFAULT 1 while staging the provider-owned PostgreSQL column", Patches: []Patch{{Path: "go/internal/provider/postgresql/migrate.go", Before: "column.Nullable = true", After: "column.Nullable = true\n\t\t\tcolumn.Default = physical.PhysicalDefault{Kind: physical.DefaultLiteral, Literal: &ir.TypedLiteralIR{Kind: ir.LiteralInteger, Canonical: \"1\"}}"}}, Gate: gate("./internal/provider/postgresql", "TestPlanIncrementalInitializesEveryConcurrencyValueToExactlyOne"), Timeout: 2 * time.Minute},
		{Label: "CONCURRENCY_SQLITE_COPIES_TWO", Summary: "copy the wrong provider literal into existing SQLite rows", Patches: []Patch{{Path: "go/internal/provider/sqlite/migrate.go", Before: `sources[index] = "1"`, After: `sources[index] = "2"`}}, Gate: gate("./internal/provider/sqlite", "TestSQLiteIncrementalInitializesConcurrencyWithProviderLiteralOne"), Timeout: 2 * time.Minute},
		{Label: "CONCURRENCY_BOOTSTRAP_IGNORES_PHYSICAL_DISAGREEMENT", Summary: "accept a physical projection that disagrees with ModelIR", Patches: []Patch{{Path: "go/internal/policy/schema/bootstrap.go", Before: "if !equalOptionalCompilerFieldID(logicalModel.OptimisticConcurrency, table.OptimisticConcurrency) {", After: "if false && !equalOptionalCompilerFieldID(logicalModel.OptimisticConcurrency, table.OptimisticConcurrency) {"}}, Gate: gate("./internal/policy/schema", "TestRegistryOptimisticConcurrencyRequiresExactThreeWayAgreement"), Timeout: 2 * time.Minute},
		{Label: "CONCURRENCY_PHYSICAL_ACCEPTS_DATABASE_DEFAULT", Summary: "allow a database default on the runtime-owned concurrency field", Patches: []Patch{{Path: "go/internal/physical/validate.go", Before: "if column.Default.Kind != DefaultNone || column.Default.Literal != nil || column.Default.Expression != nil {", After: "if false && (column.Default.Kind != DefaultNone || column.Default.Literal != nil || column.Default.Expression != nil) {"}}, Gate: gate("./internal/physical", "TestOptimisticConcurrencyPhysicalValidationRejectsEveryForgedProjection"), Timeout: 2 * time.Minute},
	}
}
